#include <queue>
#include <string>
#include <iostream>

int main() {
    std::queue<std::string> buffer;
    buffer.push("A"); // Insert at back
    buffer.push("B");

    if (!buffer.empty()) {
        std::cout << "Next: " << buffer.front() << std::endl; // Access A
        buffer.pop(); // Remove A
    }

    std::cout << "Current Last: " << buffer.back() << std::endl; // Access B
    // Output: Next: A, Current Last: B
}
